    reg clk;
    reg reset;
    wire [3:0] ena;
    wire [15:0] q;

    // Instantiate TopModule dut ( ... );
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .ena(ena),
        .q(q)
    );

    // Clock generation
    initial begin
        clk = 0;
        forever #5 clk = ~clk; // 10ns clock period
    end

    // Self-checking stimulus
    integer errors = 0;
    initial begin
        // Apply reset
        reset = 1;
        #10; // Wait for a clock cycle
        reset = 0;

        // Test the BCD counter
        // Wait for 20 clock cycles to observe the counter behavior
        repeat (20) @(posedge clk);

        // Check expected outputs
        // After 20 clock cycles, we expect q to be 0001 0010 0000 0000 (i.e., 20 in BCD)
        if (q !== 16'b0001001000000000) begin
            $display("Error: Expected q = 0001 0010 0000 0000, got q = %b", q);
            errors = errors + 1;
        end

        // Check enable signals
        if (ena !== 4'b0000) begin
            $display("Error: Expected ena = 0000, got ena = %b", ena);
            errors = errors + 1;
        end

        // Continue testing for more clock cycles
        repeat (80) @(posedge clk); // Wait for another 80 clock cycles

        // Check expected outputs after 100 clock cycles (i.e., 100 in BCD)
        if (q !== 16'b0001 0000 0000 0000) begin
            $display("Error: Expected q = 0001 0000 0000 0000, got q = %b", q);
            errors = errors + 1;
        end

        // Check enable signals
        if (ena !== 4'b0000) begin
            $display("Error: Expected ena = 0000, got ena = %b", ena);
            errors = errors + 1;
        end

        // Final check for the test result
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end
endmodule
